"""The scene catalog (config/scenes.yaml, D59) reproduces Paris's approved six scenes exactly."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from conductor.config import ConfigError
from conductor.scenes import load_scenes

# Paris's handoff (ALON-SIX-SCENES.json): 30 full-strength RGB samples per scene, generated by demo-model.mjs.
FRAMES = json.loads((Path(__file__).parent / "fixtures_scene_frames.json").read_text())
APPROVED = [
    "lowcountry-calm",
    "rainbow-row-sunset",
    "garden-gathering",
    "coastal-tides",
    "golden-hour",
    "goodnight-glow",
]


def test_the_catalog_is_exactly_the_six_approved_scenes_in_order():
    assert [s.id for s in load_scenes().scenes] == APPROVED


@pytest.mark.parametrize("scene_id", APPROVED)
def test_each_scene_reproduces_the_handoff_frame_exactly(scene_id):
    frame = load_scenes().get(scene_id).frame(30)
    assert [list(c) for c in frame] == FRAMES[scene_id]


def test_lowcountry_calm_is_mirrored_with_ivory_ends():
    calm = load_scenes().get("lowcountry-calm")
    frame = calm.frame(30)
    assert frame[0] == frame[-1] == calm.palette[0].rgb and frame[14] == frame[15]


def test_solid_fallbacks_match_the_handoff_defaults():
    """The handoff's defaults (Coastal Tides aqua, Golden Hour sunset pink, Lowcountry Calm soft ivory), as the
    pinned fixture holds them: a Design Lab export (or `make scene-pins`) regenerates the pins."""
    solids = {s.id: s.solid.name for s in load_scenes().scenes}
    pinned = {scene_id: pin["solid"] for scene_id, pin in FRAMES["_pins"].items()}
    assert solids == pinned, "approved value changed: run make scene-pins and review the fixture diff"


def test_a_bad_catalog_names_the_file_and_the_problem(tmp_path):
    (tmp_path / "scenes.yaml").write_text(
        "scenes:\n  - {id: x1, name: X, mood: m, description: d, brightness_draft: 50, default_solid: 5,"
        " palette: [{name: a, hex: '#FFFFFF'}, {name: b, hex: 'red'}]}\n"
    )
    with pytest.raises(ConfigError, match="scenes.yaml"):
        load_scenes.__wrapped__(tmp_path)
